     * The share of a dimension's aggregated usage the customer owes for once the
     * plan's allowance has been taken off.
     *
     * A dimension without an allowance bills every unit of usage. A finite
     * allowance only bills the usage beyond it, and only when the plan permits
     * overage; an unlimited (`inf`) allowance, an allowance that is not yet
     * exhausted, or a plan that forbids overage bills nothing.
     */
    static chargeableUsage({
        total,
        dimension,
    }: {
        total: number;
        dimension?: Pick<ReadDimensionResponseData, 'usageEntitlement' | 'overageAllowed'>;
    }): number {
        const usage = Number(total);
        const billableUsage = Number.isFinite(usage) ? usage : 0;
        const { usageEntitlement, overageAllowed } = dimension ?? {};
        if (usageEntitlement === undefined || usageEntitlement === null) {
            return billableUsage;
        }
        if (usageEntitlement === 'inf') {
            return 0;
        }
        const overagePermitted =
            overageAllowed === overageAllowedEnum.true || (overageAllowed as unknown as boolean) === true;
        if (!overagePermitted) {
            return 0;
        }
        const allowance = parseFloat(usageEntitlement as unknown as string);
        if (!Number.isFinite(allowance)) {
            return billableUsage;
        }
        const overage = billableUsage - allowance;
        return overage > 0 ? overage : 0;
    }

